-- Normalize accented person + artwork slugs to ASCII and repoint image_link -> somice CDN.
-- Generated from artworks/_report.json. 6 person renames, 1300 artworks.
-- (No enforced FK on artworks.painter_slug in the schema DDL, so people is updated first.)
--
-- OPTIONAL backup first (uncomment to snapshot old slugs + URLs so you can revert):
-- create table artworks_slug_backup as
--   select id, painter_slug, slug, image_link from artworks where iconic;
-- create table people_slug_backup as select id, slug from people;

begin;

-- 1. rename the accented person/painter slugs
update people as p
set slug = m.new
from (values
  ('albrecht-dürer', 'albrecht-durer'),
  ('diego-velázquez', 'diego-velazquez'),
  ('édouard-manet', 'edouard-manet'),
  ('eugène-delacroix', 'eugene-delacroix'),
  ('matthias-grünewald', 'matthias-grunewald'),
  ('nadežda-petrović', 'nadezda-petrovic')
) as m(old, new)
where p.slug = m.old;
-- Expected: UPDATE 6

-- 2. rename artworks.painter_slug + artworks.slug and set the CDN image_link (matched on OLD keys)
update artworks as a
set painter_slug = m.new_painter,
    slug        = m.new_slug,
    image_link  = m.url
from (values
  ('abanindranath-tagore', 'a-moonlight-music-party', 'abanindranath-tagore', 'a-moonlight-music-party', 'https://cdn.jsdelivr.net/gh/fjovakaric/somice@main/artworks/abanindranath-tagore/a-moonlight-music-party.webp'),
